import { Cart, Category, ErrorEvent, Identity, PartyIdentification } from '../events';
/**
Description: Checkout step in which the shopper applies a coupon to the cart.
*/
export type CheckoutApplyCoupon = {
    events: Array<Cart | Identity | PartyIdentification | ErrorEvent>;
}

export class CheckoutApplyCouponBuilder {

    private checkoutApplyCoupon: CheckoutApplyCoupon = {
        events: []
    }

    private cart!: Cart;
    private errorEvent!: ErrorEvent;
    private identity!: Identity;
    private partyIdentification!: PartyIdentification;

    public withCart(cart: Cart) : CheckoutApplyCouponBuilder {
        this.cart = cart;
        return this;
    }
    public withErrorEvent(errorEvent: ErrorEvent) : CheckoutApplyCouponBuilder {
        this.errorEvent = errorEvent;
        return this;
    }
    public withIdentity(identity: Identity) : CheckoutApplyCouponBuilder {
        this.identity = identity;
        return this;
    }
    public withPartyIdentification(partyIdentification: PartyIdentification) : CheckoutApplyCouponBuilder {
        this.partyIdentification = partyIdentification;
        return this;
    }

    public build() : CheckoutApplyCoupon {
        if(this.cart) {
            this.checkoutApplyCoupon.events.push(this.cart);
        }
        if(this.errorEvent) {
            this.checkoutApplyCoupon.events.push(this.errorEvent);
        }
        if(this.identity) {
            this.checkoutApplyCoupon.events.push(this.identity);
        }
        if(this.partyIdentification) {
            this.checkoutApplyCoupon.events.push(this.partyIdentification);
        }

        return this.checkoutApplyCoupon;
    }
}
